//! The header of a generated file (spec §4.3): where the file came from, in the comment syntax
//! of its format, and the mark that tells alz a file is its own.
//!
//! A source is named by a [`SourceRef`], which is built only from text that cannot break out of
//! the comment it is written in or hide in a terminal: no control or format character, and no
//! `-->`. A layer's file names and version are untrusted, so the refusal is an error value
//! ([`SourceRefError`]), never a stripped text.

use std::fmt;

use thiserror::Error;

use crate::layer::LayerName;
use crate::path::SafeRelPath;
use crate::render::tree::OutputPath;
use crate::stack::ResolvedLayer;
use crate::untrusted_text::Stripped;

/// The mark every generated file carries in its header.
pub const GENERATED_MARK: &str = "GENERATED by agent-layerz";
/// The mark before the rename to agent-layerz; a file that carries it still counts as generated.
pub const LEGACY_GENERATED_MARK: &str = "GENERATED by agent-layers";
/// How many bytes at the start of a file are searched for the mark.
const MARK_WINDOW: usize = 1024;
/// What ends an HTML comment.
const COMMENT_END: &str = "-->";
/// What stands for the source of a slot stub, which no layer file provides.
const SLOT_STUB: &str = "slot stub";
/// The opening line of a frontmatter block.
const FRONTMATTER_OPENING: &str = "---\n";

/// Why a text cannot be a source in a header. The error holds no input.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Error)]
pub enum SourceRefError {
    /// A control or format character: it could end the comment line or hide in a terminal.
    #[error("a source in a header must hold no control or format character")]
    Unprintable,
    /// `-->`, which would close an HTML comment early.
    #[error("a source in a header must not hold '-->'")]
    ClosesComment,
}

/// Checks a piece of a source.
fn checked(text: &str) -> Result<(), SourceRefError> {
    if Stripped::from_untrusted(text).as_str() != text {
        Err(SourceRefError::Unprintable)
    } else if text.contains(COMMENT_END) {
        Err(SourceRefError::ClosesComment)
    } else {
        Ok(())
    }
}

/// How a layer is named in a header: `<name>@<rev or version>`, or the name alone.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct LayerLabel(String);

impl LayerLabel {
    /// The label of a layer name and the revision it is written with.
    ///
    /// # Errors
    ///
    /// [`SourceRefError`] when the revision holds a control or format character or `-->`.
    pub fn new(name: &LayerName, revision: Option<&str>) -> Result<Self, SourceRefError> {
        revision.map_or_else(
            || Ok(Self(name.to_string())),
            |revision| checked(revision).map(|()| Self(format!("{name}@{revision}"))),
        )
    }

    /// The label of a resolved layer: its name, then the pin's `rev` when it has one, else its
    /// `version`, else nothing.
    ///
    /// # Errors
    ///
    /// [`SourceRefError`] when the layer's version holds a control or format character or `-->`.
    pub fn of(layer: &ResolvedLayer) -> Result<Self, SourceRefError> {
        let revision = layer.pin().map_or_else(
            || {
                layer
                    .meta()
                    .version()
                    .map(|version| version.as_str().to_owned())
            },
            |pin| Some(pin.rev.to_string()),
        );
        Self::new(layer.meta().name(), revision.as_deref())
    }
}

impl fmt::Display for LayerLabel {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// One source named in a header.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum SourceRef {
    /// A file of a layer: `personal@1.0.0:agents/architect.md`.
    LayerFile {
        /// The layer.
        label: LayerLabel,
        /// The file's path in the layer.
        path: SafeRelPath,
    },
    /// Another generated file, such as `AGENTS.md` for the header of `CLAUDE.md`.
    Output(OutputPath),
    /// A slot stub, which has no file.
    SlotStub,
}

impl SourceRef {
    /// A file of a layer.
    ///
    /// # Errors
    ///
    /// [`SourceRefError`] when the path holds a control or format character or `-->`.
    pub fn layer_file(label: LayerLabel, path: SafeRelPath) -> Result<Self, SourceRefError> {
        checked(path.as_str()).map(|()| Self::LayerFile { label, path })
    }
}

impl fmt::Display for SourceRef {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LayerFile { label, path } => write!(formatter, "{label}:{path}"),
            Self::Output(path) => path.fmt(formatter),
            Self::SlotStub => formatter.write_str(SLOT_STUB),
        }
    }
}

/// The sources a file came from, most general first. It holds at least one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Sources {
    first: SourceRef,
    rest: Vec<SourceRef>,
}

impl Sources {
    /// The sources `first` and `rest`.
    pub fn new(first: SourceRef, rest: impl IntoIterator<Item = SourceRef>) -> Self {
        Self {
            first,
            rest: rest.into_iter().collect(),
        }
    }

    /// One source.
    #[must_use]
    pub const fn single(source: SourceRef) -> Self {
        Self {
            first: source,
            rest: Vec::new(),
        }
    }

    /// The sources joined by ` + `.
    fn joined(&self) -> String {
        std::iter::once(&self.first)
            .chain(&self.rest)
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(" + ")
    }
}

/// The header text, without comment delimiters.
#[must_use]
pub fn header_text(sources: &Sources) -> String {
    format!(
        "{GENERATED_MARK} \u{2014} DO NOT EDIT. Source: {}. Edit the source and run `alz build`.",
        sources.joined()
    )
}

/// The header as an HTML comment, for Markdown without frontmatter: `AGENTS.md`, `CLAUDE.md`.
#[must_use]
pub fn html_header(sources: &Sources) -> String {
    format!("<!-- {} -->", header_text(sources))
}

/// The header as a YAML comment line, without its line feed, for the first line of a frontmatter
/// block.
#[must_use]
pub fn frontmatter_header(sources: &Sources) -> String {
    format!("# {}", header_text(sources))
}

/// A file that has no frontmatter block to put the header in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Error)]
#[error("file has no frontmatter")]
pub struct NoFrontmatter;

/// Puts the header as the first line of the frontmatter of `text`. Line endings are read as line
/// feeds throughout, as the reference reads them, and the rest of the file is kept as it is.
///
/// # Errors
///
/// [`NoFrontmatter`] when `text` does not start with `---` and a line ending.
pub fn insert_frontmatter_header(text: &str, sources: &Sources) -> Result<String, NoFrontmatter> {
    text.replace("\r\n", "\n")
        .strip_prefix(FRONTMATTER_OPENING)
        .map(|rest| {
            format!(
                "{FRONTMATTER_OPENING}{}\n{rest}",
                frontmatter_header(sources)
            )
        })
        .ok_or(NoFrontmatter)
}

/// Whether a file starting with `bytes` is one alz generated: its first kilobyte holds the
/// current mark or the legacy one.
#[must_use]
pub fn has_generated_mark(bytes: &[u8]) -> bool {
    let head = bytes.get(..MARK_WINDOW).unwrap_or(bytes);
    [GENERATED_MARK, LEGACY_GENERATED_MARK].iter().any(|mark| {
        head.windows(mark.len())
            .any(|window| window == mark.as_bytes())
    })
}

